package ru.pulsedoma.issues;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import static ru.pulsedoma.issues.CaseExchangeService.*;
import static ru.pulsedoma.issues.OperationsTypes.*;

@Service
public class CaseVisitService {
 private final JdbcTemplate db;private final ResidentCaseService cases;private final CaseWorkAccess access;private final CaseBotNotifications bot;private final ObjectMapper mapper;
 public CaseVisitService(JdbcTemplate db,ResidentCaseService cases,CaseWorkAccess access,CaseBotNotifications bot,ObjectMapper mapper){this.db=db;this.cases=cases;this.access=access;this.bot=bot;this.mapper=mapper;}
 private Map<String,Object> row(String id){var rows=db.queryForList("SELECT * FROM case_visits WHERE id=?",id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private ResidentCaseService.CaseView c(String id,String user,Integer revision){var c=cases.get(id,user);if(!c.fullAccess())throw missing();if(revision!=null){if(c.revision()!=revision)throw conflict();if(c.status()==CaseStatus.CLOSED)throw invalid("Сначала нужно повторное рассмотрение");}return c;}
 private void staff(ResidentCaseService.CaseView c,String user){if(c.isAuthor()||!(c.kind()==CaseKind.PAYMENT?access.billing(c.houseId(),user):access.coordinator(c.id(),c.houseId(),user)))throw missing();}
 private void current(Map<String,Object> v,ResidentCaseService.CaseView c){if(!access.exists("SELECT count(*) FROM organization_houses WHERE house_id=? AND organization_id=? AND status='ACTIVE'",c.houseId(),v.get("source_organization_id")))throw missing();}
 private boolean worker(String caseId,String worker){try{var c=cases.get(caseId,worker);return c.fullAccess()&&!c.isAuthor()&&c.status()!=CaseStatus.CLOSED;}catch(ru.pulsedoma.common.BusinessException e){return false;}}
 private void event(ResidentCaseService.CaseView c,String user,Action action,String entity,String note,String next){if(db.update("UPDATE resident_cases SET revision=revision+1,updated_at=?,next_step=CASE WHEN status='WAITING_RESIDENT' THEN next_step ELSE coalesce(?,next_step) END,status=CASE WHEN ? IS NOT NULL AND status<>'WAITING_RESIDENT' THEN 'IN_PROGRESS' ELSE status END WHERE id=? AND revision=?",now(),next,next,c.id(),c.revision())!=1)throw conflict();db.update("INSERT INTO case_events(id,case_id,actor_id,type,text,created_at) VALUES (?,?,?,'UPDATED',?,?)",id(),c.id(),user,note,now());bot.enqueue(c.id(),user,CaseEventType.UPDATED);try{db.update("INSERT INTO operations_history(id,house_id,case_id,entity_id,action,note,public_note,snapshot_json,actor_id,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",id(),c.houseId(),c.id(),entity,action.name(),note,note,mapper.writeValueAsString(row(entity)),user,now());}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
 public record Workspace(boolean canPlan,boolean isAuthor,List<Map<String,Object>> visits,List<ResidentCaseService.Staff> workers){}
 public Workspace workspace(String caseId,String user){var c=c(caseId,user,null);boolean plan=!c.isAuthor()&&(c.kind()==CaseKind.PAYMENT?access.billing(c.houseId(),user):access.coordinator(caseId,c.houseId(),user));var visits=db.queryForList("SELECT v.*,u.display_name AS worker_name FROM case_visits v JOIN users u ON u.id=v.worker_id WHERE v.case_id=? ORDER BY v.rowid DESC",caseId);for(var v:visits){v.put("slots",db.queryForList("SELECT id,starts_at,ends_at FROM visit_slots WHERE visit_id=? ORDER BY starts_at",v.get("id")));v.put("history",db.queryForList("SELECT public_note,created_at FROM operations_history WHERE entity_id=? ORDER BY rowid",v.get("id")));v.put("canRecord",plan||user.equals(s(v,"worker_id"))&&worker(caseId,user));v.put("canChoose",c.isAuthor()&&c.status()!=CaseStatus.CLOSED&&"OFFERED".equals(s(v,"state"))&&worker(caseId,s(v,"worker_id"))&&access.exists("SELECT count(*) FROM organization_houses WHERE house_id=? AND organization_id=? AND status='ACTIVE'",c.houseId(),v.get("source_organization_id")));}
 return new Workspace(plan&&c.status()!=CaseStatus.CLOSED,c.isAuthor(),visits,plan?access.candidates(c.houseId()).stream().filter(w->worker(caseId,w.id())).toList():List.of());}
 @Transactional public Workspace offer(String caseId,OperationsRequests.Visit r,String user){var c=c(caseId,user,r.caseRevision());staff(c,user);if(!worker(caseId,r.workerId()))throw invalid("Сначала назначьте специалисту доступ к этому обращению");
 var slots=new ArrayList<>(r.slots());slots.sort(Comparator.comparing(OperationsRequests.Slot::startsAt));Instant end=null;for(var slot:slots){if(!slot.startsAt().isAfter(Instant.now())||!slot.endsAt().isAfter(slot.startsAt())||Duration.between(slot.startsAt(),slot.endsAt()).compareTo(Duration.ofHours(8))>0||end!=null&&slot.startsAt().isBefore(end))throw invalid("Предложите разные будущие интервалы продолжительностью до 8 часов");end=slot.endsAt();}
 for(var old:db.queryForList("SELECT id FROM case_visits WHERE case_id=? AND state IN ('OFFERED','CONFIRMED','CHANGE_REQUESTED')",caseId)){db.update("UPDATE case_visits SET state='CANCELLED',report=?,revision=revision+1,updated_at=? WHERE id=?",r.reason(),now(),old.get("id"));}
 String key=id(),org=db.queryForObject("SELECT organization_id FROM organization_houses WHERE house_id=? AND status='ACTIVE' ORDER BY organization_id LIMIT 1",String.class,c.houseId());db.update("INSERT INTO case_visits(id,case_id,source_organization_id,purpose,worker_id,state,created_by,created_at,updated_at) VALUES (?,?,?,?,?,'OFFERED',?,?,?)",key,caseId,org,r.purpose(),r.workerId(),user,now(),now());for(var slot:slots)db.update("INSERT INTO visit_slots(id,visit_id,starts_at,ends_at) VALUES (?,?,?,?)",id(),key,slot.startsAt(),slot.endsAt());event(c,user,Action.VISIT_OFFERED,key,"Предложены варианты времени визита: "+r.purpose()+". "+r.reason(),"Выберите удобное время визита в карточке обращения или попросите другое");return workspace(caseId,user);}
 @Transactional public Workspace choose(String visit,OperationsRequests.VisitChoice r,String user){var v=row(visit);var c=c(s(v,"case_id"),user,r.caseRevision());current(v,c);if(!c.isAuthor())throw missing();if(rev(v)!=r.revision())throw conflict();if(!"OFFERED".equals(s(v,"state")))throw invalid("Варианты времени уже изменились");if(!worker(c.id(),s(v,"worker_id")))throw invalid("Специалист недоступен. Попросите предложить другое время");
 // Acquire the SQLite write lock before checking a worker's other reservations.
 if(db.update("UPDATE case_visits SET revision=revision WHERE id=? AND revision=?",visit,r.revision())!=1)throw conflict();var found=db.queryForList("SELECT * FROM visit_slots WHERE id=? AND visit_id=?",r.slotId(),visit);if(found.isEmpty())throw missing();var slot=found.getFirst();if(!Instant.parse(s(slot,"starts_at")).isAfter(Instant.now()))throw invalid("Это время уже прошло. Попросите новые варианты");
 if(access.exists("SELECT count(*) FROM case_visits v JOIN visit_slots s ON s.id=v.selected_slot_id WHERE v.worker_id=? AND v.state='CONFIRMED' AND v.id<>? AND julianday(s.starts_at)<julianday(?) AND julianday(s.ends_at)>julianday(?)",v.get("worker_id"),visit,slot.get("ends_at"),slot.get("starts_at")))throw invalid("Специалист уже занят в этот интервал. Выберите другой или попросите новое время");db.update("UPDATE case_visits SET state='CONFIRMED',selected_slot_id=?,revision=revision+1,updated_at=? WHERE id=?",r.slotId(),now(),visit);String when=Instant.parse(s(slot,"starts_at")).atZone(ZoneId.of("Europe/Moscow")).format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"));event(c,user,Action.VISIT_CHOSEN,visit,"Вы согласовали визит на "+when+" МСК","Визит согласован: "+when+" МСК. Время можно попросить изменить");return workspace(c.id(),user);}
 @Transactional public Workspace decision(String visit,String action,OperationsRequests.VisitDecision r,String user){var v=row(visit);var c=c(s(v,"case_id"),user,r.caseRevision());current(v,c);if(rev(v)!=r.revision())throw conflict();var state=VisitState.valueOf(s(v,"state"));if(state==VisitState.CANCELLED||state==VisitState.COMPLETED)throw invalid("Визит завершён");Action audit;String text,next;
 if(action.equals("change")){if(!c.isAuthor())throw missing();db.update("UPDATE case_visits SET state='CHANGE_REQUESTED',resident_note=? WHERE id=?",r.note(),visit);audit=Action.VISIT_CHANGE_REQUESTED;text="Вы попросили предложить другое время: "+r.note();next="Сотрудник предложит новые варианты времени визита";}
 else{if(!action.equals("complete")||!user.equals(s(v,"worker_id"))||!worker(c.id(),user))staff(c,user);if(action.equals("complete")){if(state!=VisitState.CONFIRMED||!access.exists("SELECT count(*) FROM visit_slots WHERE id=? AND datetime(starts_at)<=datetime('now')",v.get("selected_slot_id")))throw invalid("Завершить можно согласованный визит после его начала");db.update("UPDATE case_visits SET state='COMPLETED',report=? WHERE id=?",r.note(),visit);audit=Action.VISIT_COMPLETED;text="Визит состоялся: "+r.note()+". Это ещё не подтверждение решения обращения.";next="Сотрудник готовит следующий шаг по результатам визита";}else if(action.equals("cancel")){db.update("UPDATE case_visits SET state='CANCELLED',report=? WHERE id=?",r.note(),visit);audit=Action.VISIT_CANCELLED;text="Визит отменён: "+r.note();next="Сотрудник уточняет следующий шаг после отмены визита";}else throw invalid("Неизвестное действие");}
 db.update("UPDATE case_visits SET revision=revision+1,updated_at=? WHERE id=?",now(),visit);event(c,user,audit,visit,text,next);return workspace(c.id(),user);}
}
